    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof createGebouw>>, TError,{data: BodyType<GebouwInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof createGebouw>>,
        TError,
        {data: BodyType<GebouwInput>},
        TContext
      > => {
      return useMutation(getCreateGebouwMutationOptions(options));
    }

